#!/bin/zsh
# 用法: seed.sh s4|s9 [--yes]
cd "${0:A:h}/.."   # 项目根（脚本所在 scripts/ 的上一级）
K=素材/关键帧; A=素材/音频
TAIL="Use @图像1 as the first frame. Lip sync strictly to @音频1: keep the original vocals, lyrics and timing exactly, do not re-sing or change the song."
C=(xk-video --model 2.0-fast --res 480p --ratio 16:9 --duration 6)
case $1 in
s6) $C --ref $K/s6_舞台服副歌.png --audio $A/s6_22.00-28.00.mp3 --out 镜头/shot_s6_stage480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style, costume and character. Limited animation like a 1990s visual novel. Locked camera, waist-up, single shot, no cuts. 0–1.8s: she stands still under the spotlight with eyes closed and head lowered, arms down, holding her breath, hair drifting slightly. 1.9s, on the beat drop: her eyes snap open and she points straight at the camera with a big grin. 1.9–6s: she sings to the camera with precise lip sync to the audio, small head bobs on the beat, hair and ribbons blowing; 3.6s, on \"FOOM\": she throws her other arm up high in excitement; one wink near the end. $TAIL";;
s1) $C --ref $K/s1_火花之眼.png --audio $A/s1_0.80-6.80.mp3 --out 镜头/shot_s1_sparks480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style, room and character. Limited animation like a 1990s visual novel: mostly held poses with small movements. Locked camera, single shot, no cuts. 0–0.6s: she rests her chin on her hands, gazing at the CRT screen. 0.6s: she starts singing softly with lip sync to the audio. 1.8s, on \"sparks\": the pixel eyes on the CRT screen blink once and tiny star sparkles pop out of the screen. 1.8–4.5s: she leans slowly closer to the screen, her amber eyes widen and fill with sparkling star highlights, a light blush appears. 4.3s, on \"eyes\": she gives a small delighted gasp. The room stays still and dark, only the monitor glow flickers slightly. $TAIL";;
s4) $C --ref $K/s4_女仆献软盘.png --audio $A/s4_11.90-17.90.mp3 --out 镜头/shot_s4_servant480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style, room and character. Limited animation like a 1990s visual novel: mostly held poses with small movements. Locked camera, single shot, no cuts. 0–0.6s: she holds the silver tray with the floppy disk up toward the crowned monitor, smiling. 0.6s, on \"Now\": she starts singing with lip sync to the audio, looking at the camera. 1.9s, on \"servant\": she bows deeply from the waist, still holding the tray up high over her head. 3.7s, on \"boss\": she stays bowed; the smug pixel face on the CRT raises one eyebrow and its smirk grows wider. 4.3–6s: the pixel mouth on the screen keeps stretching wider and wider into a huge grin full of pointed pixel teeth, the screen glow turns from teal to red; she peeks up from her bow, startled. $TAIL";;
s9) $C --ref $K/s9_死神之眼.png --audio $A/s9_31.50-37.50.mp3 --out 镜头/shot_s9_shinigami480.mp4 ${@:2} "2D retro anime, exactly matching the reference image style and character. Limited animation like a 1990s visual novel. Locked camera, extreme close-up on her eyes, single shot, no cuts, no mouth visible. 0–1.3s: her eyes are closed, hair strands drift slightly in a dark red glow. 1.4s: her eyes slowly open, still amber, calm and cold. 2.3s, on the beat: in one sharp instant both irises turn blood red with a thin glowing ring pattern around the pupils, pupils shrink to thin slits, a red glint flashes across both eyes. 2.3–6s: she holds a piercing, unblinking stare straight at the viewer; the red irises pulse softly on the beat; the background turns deeper crimson and black. Use @图像1 as the first frame. Use @音频1 only for timing and mood.";;
esac
